{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-agents-sidebar",
  "version": "3.1.0",
  "description": "OpenCode v2 TUI sidebar for browsing OhMyOpenAgent agents and subagents",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "author": "mark <i@mark1708.ru>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Mark1708/opencode-agents-sidebar.git"
  },
  "bugs": {
    "url": "https://github.com/Mark1708/opencode-agents-sidebar/issues"
  },
  "homepage": "https://www.npmjs.com/package/opencode-agents-sidebar",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agents",
    "provider",
    "sidebar",
    "tui",
    "subagents",
    "terminal"
  ],
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "types": "./dist/tui.d.ts"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "clean": "rm -rf dist .artifacts",
    "build:index": "bun build src/index.ts --outfile dist/index.js --target bun --format esm --external @opencode/plugin --external @opencode/plugin/tui --external @opencode/theme --external @opentui/core --external @opentui/solid --external solid-js",
    "build:tui": "bun build src/tui.ts --outfile dist/tui.js --target bun --format esm --external @opencode/plugin --external @opencode/plugin/tui --external @opencode/theme --external @opentui/core --external @opentui/solid --external solid-js",
    "build:types": "bun x tsc --project tsconfig.build.json && node scripts/prune-declarations.mjs",
    "build:all": "bun run clean && bun run build:types && bun run build:index && bun run build:tui",
    "test": "bun test",
    "typecheck": "bun x tsc --noEmit",
    "verify:package": "node scripts/verify-package.mjs",
    "prepublishOnly": "echo 'Skipping build -- CI already built dist/'"
  },
  "dependencies": {
    "@opencode/plugin": "2.0.32"
  },
  "peerDependencies": {
    "@opencode/theme": "2.0.32",
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opencode/theme": "2.0.32",
    "@opentui/core": "0.5.17",
    "@opentui/solid": "0.5.17",
    "@types/bun": "latest",
    "solid-js": "1.9.12",
    "typescript": "^5.5.0"
  },
  "engines": {
    "bun": ">=1.3.0"
  }
}
